// Tür bakım bilgisi: beslenme, cinsiyet ayrımı, üreme, ömür, bakım zorluğu, yüzme bölgesi ve su sertliği (karar yok: veri sprinti E3, 2026-11-14).
// Her alan yalnızca kaynak sayfada açıkça yazana dayanır; kaynak yazmıyorsa alan yoktur ve kayıt olmaması "bilgi yok" demektir.
// Kaynak sayfa adresleri alan başına `sources` içindedir; metin çevirileri `packages/localization/translations/{en,es}-species-care.json` dosyalarındadır.
// Bu dosya yalnız tür kartı ve ayrıntı ekranı gibi gereken yerde dinamik içe aktarmayla (`import("@/data/species-care")`) yüklenir; ilk yüklemeye girmez.
// Su sertliği yalnız kaydedilir, uyumluluk hesabına girmez. Sertlik dGH (Alman derecesi); kaynak başka birim verdiyse çevrilmiştir.
// `lifespan.qualifier`: yok = aralık, atLeast = en az, upTo = en çok, about = yaklaşık, maxRecorded = kayıtlı en yüksek yaş.
// `difficulty`: easy = kaynak kolay bakım ya da yeni başlayana uygun diyor, notForBeginners = yeni başlayana önerilmiyor ya da bakımı zor,
// expertsOnly = yalnız ileri düzey akvaryumculara. Seriously Fish'in "Difficulty: N of 8" ölçeği zorluk sayılmaz.

export type CareDifficulty = "easy" | "notForBeginners" | "expertsOnly";
export type SwimLevel = "top" | "middle" | "bottom";
export type LifespanQualifier = "atLeast" | "upTo" | "about" | "maxRecorded";
export type CareSourceField = "diet" | "sexing" | "breeding" | "lifespan" | "difficulty" | "swimLevel" | "hardness";

export interface SpeciesCare {
  /** Türkçe, en çok 2 kısa cümle; çevirisi `speciesCareTranslator` ile (anahtar Türkçe metin). */
  diet?: string;
  sexing?: string;
  breeding?: string;
  lifespan?: { years: [number, number]; qualifier?: LifespanQualifier };
  difficulty?: CareDifficulty;
  /** Kaynak birden çok bölge söylüyorsa hepsi (ör. orta ve üst). */
  swimLevels?: SwimLevel[];
  /** [alt, üst] dGH; kaynak yalnız üst ya da yalnız alt sınır verdiyse öbürü `null`. */
  hardnessDgh?: [number | null, number | null];
  /** Alanı veren kaynak sayfasının adresi. */
  sources: Partial<Record<CareSourceField, string>>;
  verifiedAt: string;
}

